import subprocess, re
text=subprocess.check_output(['llvm-objdump','-d','doomgeneric_mips'], text=True, errors='ignore')
mnems=set()
for line in text.splitlines():
    if not line.strip():
        continue
    if re.match(r'^[0-9a-f]+ <', line):
        continue
    if re.match(r'^[0-9a-f]{8}:', line.strip()):
        parts=line.split('\t')
        if len(parts)>=3:
            m=parts[2].strip().split()[0]
            mnems.add(m)
    elif re.match(r'^\s*[0-9a-f]+:', line):
        parts=line.split('\t')
        if len(parts)>=3:
            m=parts[2].strip().split()[0]
            mnems.add(m)

print('count', len(mnems))
print('\n'.join(sorted(mnems)))
PY"}
